# Let me search for foreign exchange or currency tables in the JSON more carefully

import json

def search_for_rates(data, search_terms):
    """Search for tables containing exchange rate data"""
    results = []
    for elem in data['document']['elements']:
        if 'tables' in elem:
            for table in elem['tables']:
                table_str = str(table).lower()
                for term in search_terms:
                    if term.lower() in table_str:
                        results.append(table)
                        break
    return results

# Check all years for exchange rate data
search_terms = ['exchange', 'germany', 'mark', 'dollar', 'currency', 'rate', 'dem']

for year in ['1972', '1973', '1974', '1975', '1976']:
    with open(f'/app/resources/treasury_bulletin_{year}_04.json', 'r') as f:
        data = json.load(f)

    results = search_for_rates(data, search_terms)
    if results:
        print(f"\n=== {year} - Found {len(results)} potential tables ===")
        # Print first match
        for r in results[:1]:
            print(str(r)[:300])
    else:
        print(f"\n{year}: No exchange rate tables found")
EOF
